B.bw7=s(["La sand\xeda es dulce.","D\u01b0a h\u1ea5u ng\u1ecdt."],t.s)
B.bWv=s(["Bebo leche.","T\xf4i u\u1ed1ng s\u1eefa."],t.s)
B.bh2=s(["El pan huele rico.","B\xe1nh m\xec th\u01a1m qu\xe1."],t.s)
B.b49=s(["Como un huevo.","T\xf4i \u0103n tr\u1ee9ng."],t.s)
B.c_S=s(["El arroz es rico.","C\u01a1m ngon."],t.s)
B.aX0=s(["Las fresas son rojas y dulces.","D\xe2u t\xe2y \u0111\u1ecf v\xe0 ng\u1ecdt."],t.s)
B.c55=s(["El pastel de cumplea\xf1os es grande.","B\xe1nh sinh nh\u1eadt to."],t.s)
B.awj=s(["Mam\xe1 hace empanadillas.","M\u1eb9 g\xf3i b\xe1nh bao."],t.s)
B.a8u=s(["Los fideos son largos.","S\u1ee3i m\xec d\xe0i."],t.s)
B.bYG=s(["La luna es redonda.","M\u1eb7t tr\u0103ng tr\xf2n."],t.s)
B.Oe=s(["Juego con mi amigo.","T\xf4i ch\u01a1i v\u1edbi b\u1ea1n."],t.s)
B.b4w=s(["Hay muchas estrellas en el cielo.","Tr\xean tr\u1eddi c\xf3 nhi\u1ec1u sao."],t.s)
